SELECT machine_id, CAST(last_position AS TEXT) AS last_position, typeof(last_position) AS position_class, CAST(pruned_through AS TEXT) AS pruned_through, typeof(pruned_through) AS floor_class, CAST(created_at AS TEXT) AS created_at, typeof(created_at) AS created_class, CAST(updated_at AS TEXT) AS updated_at, typeof(updated_at) AS updated_class FROM machine_control_progress WHERE machine_id=?;
